// ===== سحب معاملات باي موب لآخر N يوم (لفّة على الصفحات) =====
// بيكمّل الوركفلو السريع (صفحة واحدة كل 6 دقايق): ده بيسدّ أي فجوة حصلت
// من timeout أو توقف n8n. الحفظ ON CONFLICT (id) فالتكرار مستحيل.
const token = $('توكن باي موب').first().json.token;

const DAYS      = 14;          // المدة المطلوبة
const MAX_PAGES = 25;          // حارس: أقصى عدد صفحات
const BUDGET_MS = 4 * 60000;   // حارس: أقصى وقت للنود كله (4 دقايق)
const cutoff    = Date.now() - DAYS * 24 * 60 * 60 * 1000;
const started   = Date.now();

const terminalMapping = {
  "1139384": { branch: "المعمورة",    machine: "paymob1" },
  "1157596": { branch: "المعمورة",    machine: "paymob7" },
  "1157119": { branch: "سان ستيفانو", machine: "paymob2" },
  "1029607": { branch: "سان ستيفانو", machine: "paymob3" },
  "1157121": { branch: "سان ستيفانو", machine: "paymob6" },
  "1002249": { branch: "سيدي بشر",    machine: "paymob4" },
  "1029609": { branch: "سيدي بشر",    machine: "paymob5" }
};
const allowed = Object.keys(terminalMapping);

// باي موب بيتقل فجأة: 60 ثانية لكل صفحة + 3 محاولات بفاصل متزايد
const pull = (url) => this.helpers.httpRequest({
  method: 'GET', url, headers: { Authorization: token }, json: true, timeout: 60000
});

const BASE = 'https://accept.paymob.com/api/acceptance/transactions';
const out = [], seen = new Set();
let url = BASE, page = 0, stop = false, why = 'خلصنا الصفحات', prevFirstId = null, seenOldest = null;

while (url && !stop && page < MAX_PAGES) {
  if (Date.now() - started > BUDGET_MS) { why = 'خلص وقت النود (' + (BUDGET_MS/60000) + ' دقايق)'; break; }
  page++;

  let resp = null, lastErr = null;
  for (let a = 1; a <= 3; a++) {
    try { resp = await pull(url); break; }
    catch (e) { lastErr = e; if (a < 3) await new Promise(r => setTimeout(r, a * 3000)); }
  }
  if (!resp) { why = 'فشل صفحة ' + page + ': ' + (lastErr && lastErr.message); break; }

  const rows = resp.results || [];
  if (!rows.length) { why = 'صفحة ' + page + ' رجعت فاضية'; break; }

  // الصفحة ما اتقدّمتش (باي موب بيتجاهل page) → نوقف بدل ما نلف على الفاضي
  if (prevFirstId !== null && rows[0] && rows[0].id === prevFirstId) {
    why = 'الصفحات مش بتتقدّم — الـAPI بيرجّع نفس الصفحة';
    break;
  }
  prevFirstId = rows[0] ? rows[0].id : null;

  let oldest = Infinity, added = 0;
  for (const item of rows) {
    const t = Date.parse(item.paid_at || item.created_at || '');
    if (!isNaN(t)) oldest = Math.min(oldest, t);

    if (item.success !== true) continue;              // غير الناجحة مالهاش لزمة
    if (!isNaN(t) && t < cutoff) continue;            // أقدم من المدة
    const tId = String(item.terminal_id || '').trim();
    if (!allowed.includes(tId)) continue;             // ماكينة مش بتاعتنا
    if (seen.has(item.id)) continue;                  // اتجابت قبل كده
    seen.add(item.id); added++;

    const isRefund  = item.is_refund === true || item.is_refunded === true;
    let amount      = (item.amount_cents || 0) / 100;
    const feesValue = Number(item.fees) || 0;
    const vatValue  = (Number(item.vat_cents_bigint) || 0) / 100;
    let netAmount   = amount - feesValue - vatValue;
    if (isRefund) { amount = -Math.abs(amount); netAmount = -Math.abs(netAmount); }

    const map = terminalMapping[tId];
    out.push({ json: {
      id:           item.id,
      terminal_id:  tId,
      machine_name: map.machine,
      branch:       map.branch,
      order_id:     item.order ? String(item.order.id) : null,
      type:         isRefund ? 'REFUND' : 'SALE',
      ammount:      amount.toFixed(2),
      fees:         feesValue.toFixed(2),
      vat:          vatValue.toFixed(2),
      netammount:   netAmount.toFixed(2),
      balance:      null,
      from:         null,
      to:           map.machine,
      closed:       null,
      done:         null,
      is_excess:    null,
      createdAt:    item.paid_at,
      updatedAt:    null
    }});
  }

  if (oldest !== Infinity) seenOldest = new Date(oldest).toISOString().slice(0, 10);
  console.log('صفحة ' + page + ': ' + rows.length + ' معاملة · جديد للحفظ ' + added + ' · أقدم فيها ' + seenOldest);

  if (oldest < cutoff) { why = 'وصلنا لـ' + DAYS + ' يوم'; break; }

  url = resp.next || (BASE + '?page=' + (page + 1));
  await new Promise(r => setTimeout(r, 300));         // نفَس بسيط لباي موب
}

console.log('وقفنا: ' + why + ' · صفحات ' + page + ' · للحفظ ' + out.length + ' معاملة · أقدم يوم ' + seenOldest);
return out;
